-- ============================================================
-- 53-dados-siconfi-2022-2024.sql (Gauntlet P9 · caso de teste #3 — finanças)
-- Snapshot oficial de dado ABERTO coletado da API pública do SICONFI/Tesouro
-- Nacional em 2026-08-27 (padrão db/42/db/50: Fonte/Carga com sha256 REAL do
-- bruto; idempotente). Brutos ficam fora do repositório; cada "Carga" guarda
-- o hash do corpo JSON tal como a API o serviu.
--
-- ENDPOINT (um GET por município × exercício, rate limit 1 req/s respeitado):
--   https://apidatalake.tesouro.gov.br/ords/siconfi/tt/dca
--     ?an_exercicio={2022|2023|2024}&no_anexo=DCA-Anexo I-D&id_ente={codigo IBGE 7 dígitos}
-- Valor extraído: cod_conta='TotalDespesas' × coluna='Despesas Empenhadas'
-- (Total Geral da Despesa empenhada na DCA — Declaração de Contas Anuais).
--
-- O QUE ENTRA:
-- - "Despesas orçamentárias empenhadas" (R$, SOMA): município × exercício,
--   2022–2024, subtema novo "Execução orçamentária" no tema já existente
--   "Economia — Setor Público" (Anexo A). O indicador nasce EM_ANALISE:
--   publicar é parecer humano (RG-09), nunca deste arquivo.
--
-- SEMÂNTICA DE AUSÊNCIA (RN-005) — DIFERENTE do caso SIM/SINASC (db/50):
-- - Lá o dado é de EVENTO em tabulação estadual COMPLETA: município sem linha
--   teve ZERO eventos, e o zero é materializado.
-- - AQUI o dado é DECLARATÓRIO: cada município entrega (ou não) sua DCA ao
--   SICONFI. Município sem entrega no exercício NÃO gastou zero — o dado NÃO
--   EXISTE na fonte. Por isso NENHUM zero é materializado: a ausência fica
--   SEM linha, e o motor responde 404 com contexto (RN-005), o ranking lista
--   o município em `ausentes`, e o agregado estadual soma só quem declarou.
--   A resposta bruta vazia da API (items:[]) é registrada como "Carga" com
--   LinhasLidas=0 — prova auditável de que a pergunta foi feita.
--
-- COBERTURA REAL DA COLETA (141 municípios de MT × 3 exercícios):
--   2022: 140 municípios com DCA, 1 ausentes
--   2023: 140 municípios com DCA, 1 ausentes
--   2024: 139 municípios com DCA, 2 ausentes
-- Ausências (município × exercício sem entrega na fonte):
--   2022: 5102686 (SEM_ENTREGA)
--   2023: 5105176 (SEM_ENTREGA)
--   2024: 5105176 (SEM_ENTREGA)
--   2024: 5106273 (SEM_ENTREGA)
--
-- QUALIDADE / CORTES:
-- - Só o total consolidado (TotalDespesas × Despesas Empenhadas) entra —
--   detalhamento por natureza/função fica fora (custo/benefício declarado
--   no gauntlet; P9 prova o CONTRATO, não o cubo fiscal completo).
-- - Malha-relativo: linha só entra se o código IBGE existir em "Municipio"
--   (no banco de teste a malha do seed é parcial — 12 municípios; no banco
--   real, os 141). Reaplicar não duplica (WHERE NOT EXISTS / ON CONFLICT).
-- - Coleta: 2026-08-27T22:07:44.211Z a 2026-08-27T22:19:26.797Z UTC.
-- ============================================================

INSERT INTO "Fonte" ("Fonte_Nome","Fonte_Origem","Fonte_Url","Fonte_BaseLegal","Fonte_Licenca","Fonte_Periodicidade","Fonte_VigenciaInicio","Fonte_VigenciaFim")
VALUES ('SICONFI/Tesouro Nacional — DCA Anexo I-D (despesas orçamentárias)','Secretaria do Tesouro Nacional — SICONFI (Sistema de Informações Contábeis e Fiscais do Setor Público Brasileiro)','https://apidatalake.tesouro.gov.br/ords/siconfi/tt/dca','DADO_ABERTO','Dados abertos do Tesouro Nacional (Lei 12.527/2011; LC 101/2000 art. 48)','ANUAL',NULL,NULL)
ON CONFLICT ("Fonte_Nome") DO UPDATE SET
  "Fonte_Origem"=EXCLUDED."Fonte_Origem", "Fonte_Url"=EXCLUDED."Fonte_Url",
  "Fonte_BaseLegal"=EXCLUDED."Fonte_BaseLegal", "Fonte_Licenca"=EXCLUDED."Fonte_Licenca",
  "Fonte_Periodicidade"=EXCLUDED."Fonte_Periodicidade";

-- Subtema de finanças no tema "Economia — Setor Público" (Anexo A) — padrão db/50
INSERT INTO "SubtemaConsulta" ("SubtemaConsulta_TemaId","SubtemaConsulta_Nome","SubtemaConsulta_Status")
SELECT t."TemaConsulta_Id",'Execução orçamentária','SEM_FONTE'
FROM "TemaConsulta" t WHERE t."TemaConsulta_Nome"='Economia — Setor Público'
  AND NOT EXISTS (SELECT 1 FROM "SubtemaConsulta" s WHERE s."SubtemaConsulta_TemaId"=t."TemaConsulta_Id" AND s."SubtemaConsulta_Nome"='Execução orçamentária');

-- RG-09: nasce EM_ANALISE — a publicação é parecer humano, nunca desta migração
INSERT INTO "Indicador" ("Indicador_SubtemaId","Indicador_Nome","Indicador_Unidade","Indicador_TipoAgregacao","Indicador_MetodologiaUrl","Indicador_StatusValidacao")
SELECT s."SubtemaConsulta_Id",'Despesas orçamentárias empenhadas','R$','SOMA',NULL,'EM_ANALISE'
FROM "SubtemaConsulta" s JOIN "TemaConsulta" t ON t."TemaConsulta_Id"=s."SubtemaConsulta_TemaId"
WHERE t."TemaConsulta_Nome"='Economia — Setor Público' AND s."SubtemaConsulta_Nome"='Execução orçamentária'
  AND NOT EXISTS (SELECT 1 FROM "Indicador" existente WHERE existente."Indicador_Nome"='Despesas orçamentárias empenhadas');

