INSERT INTO "Carga" ("Carga_FonteId","Carga_DataExtracao","Carga_HashSha256","Carga_CaminhoBronze","Carga_Status","Carga_LinhasLidas","Carga_LinhasQuarentena")
SELECT fonte.id, c.extracao::timestamptz, c.hash, 'snapshot://sha256/'||c.hash, 'PROMOVIDA', c.linhas, 0
FROM cargas c CROSS JOIN fonte
WHERE NOT EXISTS (SELECT 1 FROM "Carga" x WHERE x."Carga_FonteId"=fonte.id AND x."Carga_HashSha256"=c.hash);

